mutation OrderUpdate($input: OrderInput!) {
        orderUpdate(input: $input) {
            order {
                id
                name
                updatedAt
                shippingAddress {
                    firstName
                    lastName
                    company
                    address1
                    address2
                    city
                    province
                    provinceCode
                    zip
                    country
                    countryCodeV2
                    phone
                    formatted(withName: true, withCompany: true)
                    validationResultSummary
                    coordinatesValidated
                    latitude
                    longitude
                }
            }
            userErrors {
                field
                message
            }
        }
    }
